public List<String> getPluginDownloads(){
  try {
    return getContainer().getComponentByType(PluginDownloader.class).getDownloads();
  } catch (NullPointerException e) {
    // 处理getContainer()返回null的情况
    System.err.println("Container is not initialized: " + e.getMessage());
    return Collections.emptyList();
  } catch (IllegalArgumentException e) {
    // 处理getComponentByType()参数非法的情况
    System.err.println("Invalid component type: " + e.getMessage());
    return Collections.emptyList();
  }
}
